def to_plain(value, depth=0):
    if value is None or isinstance(value, (str, int, float, bool)):
        return value
    if depth > 8:
        return str(value)
    if hasattr(value, 'get_path_name'):
        try:
            return value.get_path_name()
        except Exception:
            pass
    if hasattr(value, 'to_tuple'):
        try:
            return {'struct_type':type(value).__name__,
                    'values':[to_plain(x, depth + 1) for x in value.to_tuple()]}
        except Exception:
            pass
    if hasattr(value, 'items'):
        try:
            return [{'key':to_plain(k, depth + 1),
                     'value':to_plain(v, depth + 1)} for k, v in value.items()]
        except Exception:
            pass
    if isinstance(value, (list, tuple, set)) or hasattr(value, '__iter__'):
        try:
            return [to_plain(x, depth + 1) for x in value]
        except Exception:
            pass
    return str(value)

def read_property(default_object, name):
    snake = re.sub(r'(?<!^)(?=[A-Z])', '_', name)
    snake = re.sub(r'[^a-zA-Z0-9]+', '_', snake).strip('_').lower()
    error = ''
    for candidate in (name, snake):
        try:
            plain = to_plain(default_object.get_editor_property(candidate))
            if plain is None:
                return '', ''
            if isinstance(plain, (dict, list)):
                return json.dumps(plain, ensure_ascii=False), ''
            return str(plain), ''
        except Exception as exc:
            error = str(exc)
    return '', name + ': ' + error

columns = ['BlueprintAsset', 'Group'] + FIELDS + ['Errors']
rows = []
for asset_name, asset_path, group, properties in ITEMS:
    row = dict((column, '') for column in columns)
    row['BlueprintAsset'] = asset_path
    row['Group'] = group
    try:
        blueprint_class = unreal.EditorAssetLibrary.load_blueprint_class(asset_path)
        if blueprint_class is None:
            raise RuntimeError('Could not load class for ' + asset_name)
        default_object = unreal.get_default_object(blueprint_class)
        if default_object is None:
            raise RuntimeError('Could not load class defaults for ' + asset_name)
        errors = []
        for prop in properties:
            row[prop], error = read_property(default_object, prop)
            if error:
                errors.append(error)
        row['Errors'] = '; '.join(errors)
    except Exception as exc:
        row['Errors'] = str(exc)
    rows.append(row)

output_path = os.path.join(unreal.Paths.project_saved_dir(), 'Reditus_Item_Equipment_Defaults_Review.csv')
with open(output_path, 'w', newline='', encoding='utf-8-sig') as output:
    writer = csv.DictWriter(output, fieldnames=columns)
    writer.writeheader()
    writer.writerows(rows)

failed = sum(bool(row['Errors']) for row in rows)
unreal.log('Exported {} item/equipment Blueprints ({} rows with property errors) to {}'.format(
    len(rows), failed, output_path))
